export type TextKey = keyof typeof TEXT;

/** A text in `lang` with its `{name}` slots filled. */
export function say(lang: AssistantLang, key: TextKey, vars: Record<string, string | number> = {}): string {
  const s = (TEXT[key] as Text)[lang] ?? (TEXT[key] as Text).en;
  return s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] !== undefined ? String(vars[k]) : `{${k}}`));
}
